-- Read-only after cleanup. Call through the approved project's SQL read method.
-- Checks authoritative cardinality, exact hashes and closed ACL. Full original-row
-- preservation is compared with the preflight snapshot separately, not inferred here.
DO $postflight$
DECLARE saved public.content_versions%rowtype;
BEGIN
 IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>23 THEN RAISE EXCEPTION 'Expected 23 history records after two new tracked migrations'; END IF;
 IF (SELECT count(*) FROM public.growth_opportunities WHERE id='9bafbb2f-eea7-48ea-bc23-3896897f19c3' AND organization_id='93a88055-0a0b-40c0-b22f-a6d312320001' AND entry_kind='url_result' AND status='url_pending_review')<>1 THEN RAISE EXCEPTION 'Parent changed'; END IF;
 IF (SELECT count(*) FROM public.content_versions WHERE opportunity_id='9bafbb2f-eea7-48ea-bc23-3896897f19c3' AND organization_id='93a88055-0a0b-40c0-b22f-a6d312320001')<>2 THEN RAISE EXCEPTION 'Expected v1 and v2 only'; END IF;
 SELECT * INTO STRICT saved FROM public.content_versions WHERE first_result_request_id='a326f6ce-03c7-4d3e-9fce-c22b2849cb48';
 IF saved.organization_id<>'93a88055-0a0b-40c0-b22f-a6d312320001' OR saved.opportunity_id<>'9bafbb2f-eea7-48ea-bc23-3896897f19c3' OR saved.created_by<>'e85f1a90-3565-4fc1-a7e0-3b7d08830d0e' OR saved.version_number<>2 OR saved.first_result_expected_version<>1 OR saved.status<>'draft' OR saved.first_result_request_digest<>'pg-jsonb-sha256:3bf2931ccc19769162d780220d346be4eb9b494bec3c8da39b50c7ac3ab497f2' OR saved.first_result_request_digest IS DISTINCT FROM private.fr_request_digest(saved.organization_id,saved.opportunity_id,saved.created_by,saved.first_result_request_id,1,saved.first_result_payload) THEN RAISE EXCEPTION 'Exact v2 mismatch'; END IF;
 IF (SELECT count(*) FROM public.audit_events WHERE event_type='url_result_draft_saved' AND organization_id=saved.organization_id AND actor_user_id=saved.created_by AND object_type='content_version' AND object_id=saved.id AND details->>'request_id'=saved.first_result_request_id::text AND details->>'request_digest'=saved.first_result_request_digest AND details->>'created_parent'='false' AND details->>'version_number'='2')<>1 THEN RAISE EXCEPTION 'Expected one bound audit'; END IF;
 IF EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid IN ('public.save_url_result_draft(uuid,uuid,uuid,integer,jsonb)'::regprocedure,'private.save_url_result_draft_impl(uuid,uuid,uuid,integer,jsonb)'::regprocedure) AND a.grantee=0 AND a.privilege_type='EXECUTE') OR EXISTS(SELECT 1 FROM (VALUES('anon'),('authenticated'),('service_role')) r(name) CROSS JOIN (VALUES('public.save_url_result_draft(uuid,uuid,uuid,integer,jsonb)'::regprocedure),('private.save_url_result_draft_impl(uuid,uuid,uuid,integer,jsonb)'::regprocedure)) f(id) WHERE has_function_privilege(r.name,f.id,'EXECUTE')) THEN RAISE EXCEPTION 'Save remains executable'; END IF;
END $postflight$;
SELECT id,organization_id,opportunity_id,version_number,status,created_by,first_result_request_id,first_result_expected_version,first_result_request_digest,first_result_payload FROM public.content_versions WHERE organization_id='93a88055-0a0b-40c0-b22f-a6d312320001' AND opportunity_id='9bafbb2f-eea7-48ea-bc23-3896897f19c3' ORDER BY version_number;
